  Definition scK1 (gp tp s11 : word) (F : bvmap 5 word) (fc : bv 32) (s : as_St H) (LB : list block) (LF : list fframe)
      (bs ioc D N allocb regb cfgb schedb lo B shi : Z) (sp ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 : word) (jbs : list byte) (m0 : mem) (mo : Model)
      : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m (errv : word) (s' : as_St H) (spa ff fp : Z) (gap : list cell)
                    (p0 p8 p16 j16 j32 : list byte) (h3 : word)
                    (p1 : bptr) (v : Z) (p2 : bptr) (q : Z) (p3 : bptr) (stb : Z) (p4 : bptr) (va : Z) (XS : list (Z * Z)),
      as_VIS H s' (cfg_ms c) = MS (mkR (Z_to_bv 64 P_SC_RET_MI) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
                                       (Z_to_bv 64 ff) (Z_to_bv 64 bs) (Z_to_bv 64 D) (Z_to_bv 64 N) (Z_to_bv 64 (ff + 32)) (Z_to_bv 64 (ff + 64))
                                       (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
                                  F (ret_pc (Z_to_bv 64 P_SC_RET_MI)) fc None m (seg_rom asegs)
      /\ (spa = bv_unsigned sp + -128 \/ spa = bv_unsigned sp + -144) /\ fresh_frame H LF 1 ff fp
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv asegs m /\ stk asegs m lo spa
      /\ rw_cells asegs m (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m B /\ as_RHEAP H s LB m0 /\ as_RFS H LF m0
      /\ rw_cells asegs m spa [CB 8 p0; CB 8 p8; CB 8 p16; C8 (Z_to_bv 64 ff)]
      /\ rw_cells asegs m (spa + 32) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 32)
      /\ rw_cells asegs m (bv_unsigned sp + -96) (hz_saved s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
